CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE dining_tables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,qr_public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE table_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,table_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,branch_id,table_id) REFERENCES dining_tables(tenant_id,branch_id,id));
CREATE TABLE menu_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,external_id text,name text NOT NULL,price_satang integer NOT NULL CHECK(price_satang>=0),available boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,branch_id,id),UNIQUE(tenant_id,branch_id,external_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,table_session_id uuid NOT NULL REFERENCES table_sessions(id),status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','sent_to_pos','pos_accepted','preparing','ready','served','cancelled')),total_satang integer NOT NULL CHECK(total_satang>=0),external_pos_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,branch_id,id),UNIQUE(tenant_id,branch_id,external_pos_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),menu_item_id uuid NOT NULL REFERENCES menu_items(id),name_snapshot text NOT NULL,unit_price_satang integer NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),line_total_satang integer NOT NULL,note text NOT NULL DEFAULT '');
CREATE TABLE idempotency_records(tenant_id uuid NOT NULL,branch_id uuid NOT NULL,key text NOT NULL,request_hash text NOT NULL,order_id uuid NOT NULL REFERENCES orders(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,branch_id,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE INDEX outbox_pending_idx ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE connector_deliveries(event_id uuid PRIMARY KEY REFERENCES outbox_events(id),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,last_error text,acknowledged_at timestamptz);
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL REFERENCES orders(id),method text NOT NULL CHECK(method IN ('cash','promptpay')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','failed','refunded')),amount_satang integer NOT NULL CHECK(amount_satang>=0),provider_reference text UNIQUE,confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid,branch_id uuid,actor text NOT NULL,action text NOT NULL,resource_id text,created_at timestamptz NOT NULL DEFAULT now());
-- Application code must enforce tenant-scoped queries; RLS policies should be enabled
-- before exposing additional database roles or analytics connections.
